// W34 nightly retention context. No PII. Periods come from .env so the practitioner can change them without a
// workflow edit. Defaults = privacy notice draft (deliverables/contracts-drafter/consent-and-privacy.md, "How long
// we keep it"): non-fit form entries 24 h; details and messages 12 months after last contact; consent record and
// opt-out 5 years. A value that is not a whole number, or is below its floor, is REFUSED: that job is skipped and a
// red alert goes out. A typo must never purge early. All arithmetic is here (one place, tested); the SQL only
// compares against the cutoffs. Africa/Johannesburg has no DST, so SAST = UTC+2 for calendar arithmetic.
const H = 3600000, SAST = 2 * H;
const now = Date.now();
const refused = [];
const env = (k) => { const v = $env[k]; return v === undefined || v === null || String(v).trim() === '' ? undefined : String(v).trim(); };
function int(name, dflt, floor) {
  const raw = env(name);
  if (raw === undefined) return dflt;
  const n = Number(raw);
  if (!/^-?\d+$/.test(raw) || !Number.isInteger(n) || n < floor) { refused.push(name + '=' + raw); return null; }
  return n;
}
// Calendar months back from a SAST wall-clock instant; day clamped to the month's last day (never purges early).
function minusMonths(t, m) {
  const d = new Date(t + SAST);
  const y = d.getUTCFullYear(), mo = d.getUTCMonth() - m;
  const last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();
  return Date.UTC(y, mo, Math.min(d.getUTCDate(), last), d.getUTCHours(), d.getUTCMinutes(), d.getUTCSeconds(), d.getUTCMilliseconds()) - SAST;
}
const p = {
  nonfit_hours: int('W34_NONFIT_RETENTION_HOURS', 24, 1),
  lead_months: int('W34_LEAD_RETENTION_MONTHS', 12, 1),
  consent_years: int('W34_CONSENT_RETENTION_YEARS', 5, 1),
  wa_grace_hours: int('W34_WA_THREAD_GRACE_HOURS', 0, 0),
  wa_max_hours: int('W34_WA_THREAD_MAX_HOURS', 72, 1),
  dsr_record_years: int('W34_DSR_RECORD_YEARS', 5, 1),
};
let batch = int('W34_BATCH_LIMIT', 500, 1);
if (batch === null) batch = 500; // not a period: fall back, still reported as refused
// Invariant: the consent record must outlive the lead data it is evidence for.
if (p.lead_months !== null && p.consent_years !== null && p.consent_years * 12 < p.lead_months) {
  refused.push('W34_CONSENT_RETENTION_YEARS shorter than W34_LEAD_RETENTION_MONTHS');
  p.consent_years = null;
}
const iso = (t) => (t === null ? '' : new Date(t).toISOString());
const day = new Date(now + SAST).toISOString().slice(0, 10);
return [{ json: {
  run_id: 'W34-nightly-' + day,
  run_day: day,
  run_month: day.slice(0, 7),
  run_started_at: iso(now),
  test_mode: String($env.W34_TEST_MODE || 'false') === 'true',
  dry_run: String($env.W34_DRY_RUN || 'false') === 'true',
  evidence_dir: $env.W34_EVIDENCE_DIR || '/home/node/compliance/evidence/w34',
  batch,
  periods: p,
  refused,
  cutoffs: {
    nonfit_before: p.nonfit_hours === null ? '' : iso(now - p.nonfit_hours * H),
    lead_before: p.lead_months === null ? '' : iso(minusMonths(now, p.lead_months)),
    consent_before: p.consent_years === null ? '' : iso(minusMonths(now, p.consent_years * 12)),
    wa_expired_before: p.wa_grace_hours === null ? '' : iso(now - p.wa_grace_hours * H),
    wa_stale_before: p.wa_max_hours === null ? '' : iso(now - p.wa_max_hours * H),
    dsr_record_before: p.dsr_record_years === null ? '' : iso(minusMonths(now, p.dsr_record_years * 12)),
  },
  policy: {
    nonfit: p.nonfit_hours === null ? '' : 'unqualified_' + p.nonfit_hours + 'h',
    lead: p.lead_months === null ? '' : p.lead_months + 'm_after_last_contact',
    consent: p.consent_years === null ? '' : 'consent_' + p.consent_years + 'y',
    wa: 'wa_thread_expired',
    dsr_record: p.dsr_record_years === null ? '' : 'dsr_record_' + p.dsr_record_years + 'y',
  },
} }];

// Media files referenced by erased rows (voice notes, call recordings). URLs only; deleted by the next node.
const ctx = $('Set retention context').first().json;
const urls = [];
for (const n of ['Pseudonymise after lead retention']) {
  try { for (const u of ($(n).first().json.media_urls || [])) if (u) urls.push(u); } catch (e) { /* node failed: reported in the summary */ }
}
return [{ json: { run_id: ctx.run_id, urls: [...new Set(urls)], any: urls.length > 0 && !ctx.dry_run } }];

// W34 nightly evidence: counts only, no PII. Feeds the monthly report and obligation P8.
const ctx = $('Set retention context').first().json;
const JOBS = ['Purge expired wa_threads', 'Delete non-fit entries', 'Pseudonymise after lead retention', 'Clear residual identifiers', 'Delete consent records after consent retention', 'Minimise closed DSR records'];
const jobs = {}; const errors = [];
for (const n of JOBS) {
  let items = [];
  try { items = $(n).all().map((i) => i.json); } catch (e) { errors.push(n + ': did not run'); continue; }
  const err = items.find((j) => j && j.error);
  if (err) { errors.push(n + ': ' + String(err.error.message || err.error).slice(0, 200)); continue; }
  const j = items[0] || {};
  jobs[n] = n === 'Clear residual identifiers' ? { done: items.filter((x) => x && x.id).length } : { due: j.due ?? null, done: j.done ?? 0 };
}
let media = { requested: 0, failed: false };
try { const m = $('Collect media to erase').first().json; media.requested = (m.urls || []).length; } catch (e) {}
try { const r = $('Erase media files (storage)').first().json; if (r && r.error) { media.failed = true; errors.push('media erase: ' + String(r.error.message || r.error).slice(0, 200)); } } catch (e) {}
const red = errors.length > 0 || ctx.refused.length > 0;
return [{ json: {
  run_id: ctx.run_id, run_day: ctx.run_day, run_month: ctx.run_month, evidence_dir: ctx.evidence_dir,
  test_mode: ctx.test_mode, dry_run: ctx.dry_run, periods: ctx.periods, cutoffs: ctx.cutoffs, refused: ctx.refused,
  jobs, media, errors, red,
  alert: red ? { kind: 'w34_retention_failure', workflow: 'W34', to: ['jonathan'], severity: 'red',
    message: 'W34 retention ' + ctx.run_day + ': ' + (ctx.refused.length ? 'refused settings ' + ctx.refused.join(', ') + '. ' : '') + (errors.length ? errors.join(' | ') : '') } : null,
} }];

// W34 DSR intake normaliser. Email (howzit@) or manual webhook. The subject's contact is hashed with the same rules
// as W24/W15 (mobile: E.164 digits, SHA-256; email: smc_hash_contact = SHA-256 of lower(trim)) so the request is
// matched to leads without copying the number around. The 30-day clock starts at receipt.
const crypto = require('crypto');
const sha = (s) => crypto.createHash('sha256').update(String(s), 'utf8').digest('hex');
const DAY = 86400000;
const KINDS = ['access', 'correct', 'erase', 'object'];
const CHANNELS = ['portal', 'email', 'whatsapp', 'post', 'other'];
let dueDays = Number($env.W34_DSR_DUE_DAYS || 30);
if (!Number.isInteger(dueDays) || dueDays < 1 || dueDays > 30) dueDays = 30; // never longer than the 30 days the notice promises
const e164 = (raw) => {
  let d = String(raw || '').replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2); else if (d.startsWith('0')) d = '27' + d.slice(1);
  return /^27\d{9}$/.test(d) ? d : null;
};
const emailNorm = (s) => { const e = String(s || '').trim().toLowerCase(); return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) ? e : null; };
function classify(text) {
  const t = String(text || '').toLowerCase();
  if (/\bforget me\b|right to be forgotten|\b(delete|erase|remove)\b[^.?!]{0,40}\b(my|me)\b/.test(t)) return 'erase';
  if (/\bobject(ion)?\b[^.?!]{0,40}\b(processing|marketing|use)\b/.test(t)) return 'object';
  if (/\b(correct|update|change)\b[^.?!]{0,30}\bmy (details|information|data|number|name|email|surname)\b/.test(t)) return 'correct';
  if (/\b(what|which) (personal )?(information|data|details) do you (hold|have|keep)\b|\bcopy of (all )?my (personal )?(information|data|details)\b|\baccess (request|to my)\b|\bpaia\b|\bpopia request\b|\bsubject access\b/.test(t)) return 'access';
  return null;
}
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const now = Date.now();
  if (j.body && typeof j.body === 'object' && j.headers) {
    const b = j.body;
    const kind = String(b.kind || '').toLowerCase();
    if (!KINDS.includes(kind)) throw new Error('W34 intake: kind must be one of ' + KINDS.join('/'));
    const channel = CHANNELS.includes(String(b.channel || '').toLowerCase()) ? String(b.channel).toLowerCase() : 'other';
    const mobile = e164(b.contact) || e164(b.mobile);
    const email = emailNorm(b.contact) || emailNorm(b.email);
    const leadId = /^[0-9a-f-]{36}$/i.test(String(b.lead_id || '')) ? String(b.lead_id).toLowerCase() : null;
    if (!mobile && !email && !leadId) throw new Error('W34 intake: need a mobile, an email or a lead_id');
    const received = b.received_at && !Number.isNaN(Date.parse(b.received_at)) ? Date.parse(b.received_at) : now;
    const ref = String(b.request_ref || (kind + '|' + (mobile || email || leadId) + '|' + new Date(received + 7200000).toISOString().slice(0, 10)));
    out.push({ json: { kind, channel, requester: b.requester ? String(b.requester).slice(0, 120) : null,
      requester_contact: email || (mobile ? '+' + mobile : null), subject_hash: email ? sha(email) : null, mobile_hash: mobile ? sha(mobile) : null,
      lead_id: leadId, received_at: new Date(received).toISOString(), due_at: new Date(received + dueDays * DAY).toISOString(),
      dedupe_key: 'dsar:' + sha('webhook:' + ref).slice(0, 32), source_ref: 'webhook:' + sha(ref).slice(0, 12) } });
    continue;
  }
  if (j.subject !== undefined || j.bodyPreview !== undefined) {
    const kind = classify((j.subject || '') + ' \n ' + (j.bodyPreview || ''));
    if (!kind) continue; // not a data-subject request: W34 ignores it (W17 / people handle the rest)
    const from = (j.from && j.from.emailAddress) || {};
    const email = emailNorm(from.address);
    const m = String((j.subject || '') + ' ' + (j.bodyPreview || '')).match(/(?:\+?27|0)[\s-]?\d{2}[\s-]?\d{3}[\s-]?\d{4}/);
    const mobile = m ? e164(m[0]) : null;
    const received = j.receivedDateTime && !Number.isNaN(Date.parse(j.receivedDateTime)) ? Date.parse(j.receivedDateTime) : now;
    out.push({ json: { kind, channel: 'email', requester: from.name ? String(from.name).slice(0, 120) : null,
      requester_contact: email, subject_hash: email ? sha(email) : null, mobile_hash: mobile ? sha(mobile) : null,
      lead_id: null, received_at: new Date(received).toISOString(), due_at: new Date(received + dueDays * DAY).toISOString(),
      dedupe_key: 'dsar:' + sha('email:' + (j.id || received)).slice(0, 32), source_ref: 'email:' + sha(String(j.id || received)).slice(0, 12) } });
  }
}
return out;

// One W22 alert per new request (duplicates are silent). No name or contact in the alert.
const out = [];
for (const i of $input.all()) {
  const j = i.json;
  if (!j.dsr_id || j.duplicate) continue;
  out.push({ json: { kind: 'dsar_received', workflow: 'W34', to: [$env.W34_IO_RECIPIENT || 'jonathan'], severity: 'amber', dsr_id: j.dsr_id,
    deep_link: ($env.CONSOLE_URL || '') + '/compliance/dsr/' + j.dsr_id,
    message: 'New data-subject request (' + j.kind + '). Due ' + String(j.due_at).slice(0, 10) + '. Leads matched: ' + j.matched_leads + '. Verify identity first.' } });
}
return out;

// W34 30-day clock. red = past due_at (POPIA answer missed: W22 Red, both phones). amber = W34_DSR_WARN_DAYS or fewer
// days left, or identity still unverified W34_DSR_VERIFY_DAYS after receipt. One ticket per request per SAST day.
const D = 86400000, SAST = 7200000;
const now = Date.now();
const int = (k, d, lo, hi) => { const n = Number($env[k]); return Number.isInteger(n) && n >= lo && n <= hi ? n : d; };
const warn = int('W34_DSR_WARN_DAYS', 7, 1, 29);
const verify = int('W34_DSR_VERIFY_DAYS', 5, 1, 29);
const day = new Date(now + SAST).toISOString().slice(0, 10);
const tickets = [];
for (const i of $input.all()) {
  const r = i.json;
  if (!r || !r.id || ['completed', 'rejected'].includes(r.status)) continue;
  const due = Date.parse(r.due_at);
  const left = (due - now) / D;
  let severity = null; let why = '';
  if (now > due) { severity = 'red'; why = 'overdue by ' + Math.ceil((now - due) / D) + ' day(s)'; }
  else if (left <= warn) { severity = 'amber'; why = Math.ceil(left) + ' day(s) left'; }
  else if (!r.verified_at && now - Date.parse(r.received_at) > verify * D) { severity = 'amber'; why = 'identity not verified after ' + verify + ' days'; }
  if (!severity) continue;
  tickets.push({ dsr_id: r.id, severity, days_left: Math.ceil(left), dedupe_key: 'dsar-clock:' + r.id + ':' + day,
    what: 'DSR ' + r.kind + ' (' + String(r.id).slice(0, 8) + '): ' + why + '. Due ' + new Date(due + SAST).toISOString().slice(0, 10) + '.' });
}
const red = tickets.filter((t) => t.severity === 'red').length;
return [{ json: { day, tickets, count: tickets.length, red, amber: tickets.length - red, any: tickets.length > 0 } }];

const c = $('DSR clock').first().json;
return [{ json: { kind: c.red ? 'dsar_overdue' : 'dsar_due', workflow: 'W34', to: c.red ? ['jonathan', 'kg'] : [$env.W34_IO_RECIPIENT || 'jonathan'],
  severity: c.red ? 'red' : 'amber', deep_link: ($env.CONSOLE_URL || '') + '/compliance/dsr',
  message: c.red + ' data-subject request(s) overdue, ' + c.amber + ' due soon or unverified (' + c.day + ').' } }];

// Guard: the IO types the request id twice; action must match a supported statement. Correction is done by hand in
// the console (a person edits the field); objection runs W15 (STOP path).
const b = ($input.first().json || {}).body || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const action = String(b.action || '').toLowerCase();
if (!['export', 'erase'].includes(action)) throw new Error('W34 action must be export or erase');
if (!UUID.test(String(b.dsr_id || '')) || String(b.dsr_id).toLowerCase() !== String(b.confirm_dsr_id || '').toLowerCase()) throw new Error('W34 action: dsr_id missing or not confirmed');
let eraseAction = String($env.W34_DSR_ERASE_ACTION || 'pseudonymise').toLowerCase();
if (!['pseudonymise', 'delete'].includes(eraseAction)) eraseAction = 'pseudonymise';
return [{ json: { dsr_id: String(b.dsr_id).toLowerCase(), action, erase_action: eraseAction,
  export_dir: $env.W34_EXPORT_DIR || '/home/node/compliance/dsr-exports' } }];

// IO confirmation + broker notice (privacy notice: we tell the adviser, who must delete unless a law requires a record).
// Broker gets first name only, as W15 does. W22 renders and sends; W34 never messages anyone directly.
const s = $('Suppress subject (erase step 1)').first().json;
const c = $input.first().json || {};
const out = [{ json: { kind: 'dsar_erased', workflow: 'W34', to: [$env.W34_IO_RECIPIENT || 'jonathan'], severity: c.in_time === false ? 'red' : 'info',
  dsr_id: s.dsr_id, message: 'DSR ' + String(s.dsr_id).slice(0, 8) + ': ' + s.leads_found + ' lead(s) erased, ' + s.suppressed + ' number(s) suppressed. ' + (c.in_time === false ? 'Completed AFTER the 30-day due date.' : 'Inside 30 days.') } }];
for (const b of s.broker_notices || []) out.push({ json: { kind: 'broker_dsr_erase', workflow: 'W34', to_broker_id: b.broker_id, severity: 'info', first_name: b.first_name || null,
  message: 'A client you received from us (' + (b.first_name || 'name withheld') + ') has asked for their details to be deleted. Please delete them from your own records unless a law requires you to keep them.' } });
return out;

// Previous calendar month in SAST. No PII.
const SAST = 7200000;
const d = new Date(Date.now() + SAST);
const prev = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() - 1, 1));
const month = prev.toISOString().slice(0, 7);
return [{ json: { month, evidence_dir: $env.W34_EVIDENCE_DIR || '/home/node/compliance/evidence/w34', test_mode: String($env.W34_TEST_MODE || 'false') === 'true' } }];

// W34 monthly POPIA operations report (register P7/P8 evidence; compliance-register monthly line 4). PII-free.
const m = $('Set report month').first().json;
const s = $('Monthly POPIA stats').first().json || {};
const nights = $input.all().map((i) => (i.json && i.json.data) || i.json).filter((n) => n && n.run_day && String(n.run_day).startsWith(m.month));
const [y, mo] = m.month.split('-').map(Number);
const daysInMonth = new Date(Date.UTC(y, mo, 0)).getUTCDate();
const days = new Set(nights.map((n) => n.run_day));
const missing = [];
for (let d = 1; d <= daysInMonth; d++) { const k = m.month + '-' + String(d).padStart(2, '0'); if (!days.has(k)) missing.push(k); }
const redNights = nights.filter((n) => n.red).map((n) => n.run_day).sort();
const purged = s.purged || [];
const lines = [
  '# W34 POPIA operations: ' + m.month,
  '',
  '## Retention purge',
  'Nights run: ' + days.size + ' of ' + daysInMonth + (missing.length ? ' (missing: ' + missing.join(', ') + ')' : '') + '.',
  'Nights with an error or refused setting: ' + (redNights.length ? redNights.join(', ') : 'none') + '.',
  '',
  '| Table | Action | Policy | Rows |',
  '|---|---|---|---|',
  ...(purged.length ? purged.map((p) => '| ' + p.table_name + ' | ' + p.action + ' | ' + p.policy + ' | ' + p.rows + ' |') : ['| (nothing purged) | | | 0 |']),
  '',
  '## Data-subject requests',
  'Received: ' + (s.dsr_received ?? 0) + '. Completed: ' + (s.dsr_completed ?? 0) + ' (late: ' + (s.dsr_completed_late ?? 0) + '). Open and overdue now: ' + (s.dsr_overdue_now ?? 0) + '. Numbers suppressed on erase: ' + (s.dsr_suppressed ?? 0) + '.',
  '',
  '## Never deleted by W34',
  'public.suppression (hashes), public.audit_log, public.retention_log.',
  '',
  'Generated ' + new Date().toISOString() + ' by W34. Counts only; no personal information in this file.',
];
const red = missing.length > 0 || redNights.length > 0 || (s.dsr_overdue_now ?? 0) > 0 || (s.dsr_completed_late ?? 0) > 0;
return [{ json: { month: m.month, evidence_dir: m.evidence_dir, test_mode: m.test_mode, report_md: lines.join('\n'), red,
  alert: { kind: 'w34_monthly_report', workflow: 'W34', to: ['jonathan'], severity: red ? 'amber' : 'info',
    message: 'W34 ' + m.month + ': ' + days.size + '/' + daysInMonth + ' nights, ' + purged.reduce((a, p) => a + p.rows, 0) + ' rows purged, DSR received ' + (s.dsr_received ?? 0) + ', overdue ' + (s.dsr_overdue_now ?? 0) + '.' } } }];
